<?php

namespace App\Http\Controllers\Site;

use App\Http\Controllers\Controller;
use App\Support\Site\RobotsTxt;
use Illuminate\Http\Response;

/**
 * GET /robots.txt, generated by App\Support\Site\RobotsTxt (public/robots.txt must not exist).
 */
class RobotsController extends Controller
{
    public function __invoke(RobotsTxt $robots): Response
    {
        return response($robots->render(), 200, [
            'Content-Type' => 'text/plain; charset=UTF-8',
            'X-Content-Type-Options' => 'nosniff',
        ]);
    }
}
